    bronze_glassgatheringiron = { name = "Bronast zbiralna železna palica", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zbiralna železna palica za steklarje." },
    silver_glassgatheringiron = { name = "Srebrn zbiralna železna palica", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zbiralna železna palica za steklarje." },
    gilded_glassgatheringiron = { name = "Pozlačen zbiralna železna palica", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zbiralna železna palica za steklarje." },
    jewel_set_glassgatheringiron = { name = "Draguljast zbiralna železna palica", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zbiralna železna palica za steklarje." },
    royal_sovereign_glassgatheringiron = { name = "Kraljevski suveren zbiralna železna palica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren zbiralna železna palica z biseri za krono." },
}
local BUILDINGS = {
    glassgatheringiron_workshop = { name = "Glassgatheringiron delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
