GlassGatheringIronMaker.ironStock=18; GlassGatheringIronMaker.bronzeStock=14; GlassGatheringIronMaker.woodStock=10; GlassGatheringIronMaker.leatherStock=8; GlassGatheringIronMaker.silverStock=8; GlassGatheringIronMaker.goldStock=6; GlassGatheringIronMaker.jewelStock=4; GlassGatheringIronMaker.pearlStock=4
GlassGatheringIronMaker.productStock = {}; GlassGatheringIronMaker.buildings = {}; GlassGatheringIronMaker.maker = nil; GlassGatheringIronMaker.activeMaking = {}; GlassGatheringIronMaker.totalProducts = 0; GlassGatheringIronMaker.dayTimer = 0
function GlassGatheringIronMaker.init() GlassGatheringIronMaker.ironStock=18; GlassGatheringIronMaker.bronzeStock=14; GlassGatheringIronMaker.woodStock=10; GlassGatheringIronMaker.leatherStock=8; GlassGatheringIronMaker.silverStock=8; GlassGatheringIronMaker.goldStock=6; GlassGatheringIronMaker.jewelStock=4; GlassGatheringIronMaker.pearlStock=4; GlassGatheringIronMaker.productStock={}; GlassGatheringIronMaker.buildings={}; GlassGatheringIronMaker.maker=nil; GlassGatheringIronMaker.activeMaking={}; GlassGatheringIronMaker.totalProducts=0; GlassGatheringIronMaker.dayTimer=0; print("[GlassGatheringIronMaker] Royal Glass Gathering Iron Maker System initialized (6 products, 4 buildings)") end
function GlassGatheringIronMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassGatheringIronMaker.maker={name=n or ("Paličar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Paličar najet: %s (spretnost: %d)",GlassGatheringIronMaker.maker.name,s),"success") end; return true end
function GlassGatheringIronMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassGatheringIronMaker.build(id) local ok,e=GlassGatheringIronMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassGatheringIronMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassGatheringIronMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassGatheringIronMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassGatheringIronMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassGatheringIronMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassGatheringIronMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassGatheringIronMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassGatheringIronMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassGatheringIronMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassGatheringIronMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassGatheringIronMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassGatheringIronMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassGatheringIronMaker.buildings==0 then return false,"Potrebna palična delavnica" end; if not GlassGatheringIronMaker.maker then return false,"Potreben palicar" end; return true end
function GlassGatheringIronMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassGatheringIronMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassGatheringIronMaker.ironStock=GlassGatheringIronMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassGatheringIronMaker.bronzeStock=GlassGatheringIronMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassGatheringIronMaker.woodStock=GlassGatheringIronMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassGatheringIronMaker.leatherStock=GlassGatheringIronMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassGatheringIronMaker.silverStock=GlassGatheringIronMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassGatheringIronMaker.goldStock=GlassGatheringIronMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassGatheringIronMaker.jewelStock=GlassGatheringIronMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassGatheringIronMaker.pearlStock=GlassGatheringIronMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassGatheringIronMaker.maker then t=math.max(1,t-math.floor(GlassGatheringIronMaker.maker.skill/13)) end; table.insert(GlassGatheringIronMaker.activeMaking,{id="glassgatheringiron_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassGatheringIronMaker.completeMaking(m) local q=1.0+(GlassGatheringIronMaker.getQualityBonus()/100); if GlassGatheringIronMaker.maker then q=q+(GlassGatheringIronMaker.maker.skill/140) end; q=math.min(2.5,q); GlassGatheringIronMaker.productStock[m.productType]=(GlassGatheringIronMaker.productStock[m.productType] or 0)+m.quantity; GlassGatheringIronMaker.totalProducts=GlassGatheringIronMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassGatheringIronMaker.maker then GlassGatheringIronMaker.maker.itemsMade=GlassGatheringIronMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassGatheringIronMaker.maker.skill=math.min(100,GlassGatheringIronMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Palica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassgatheringiron.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassGatheringIronMaker.update(dt) if not _G.state then return end; GlassGatheringIronMaker.dayTimer=GlassGatheringIronMaker.dayTimer+dt; if GlassGatheringIronMaker.dayTimer>=30 then GlassGatheringIronMaker.dayTimer=0; for i=#GlassGatheringIronMaker.activeMaking,1,-1 do local m=GlassGatheringIronMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassGatheringIronMaker.completeMaking(m); table.remove(GlassGatheringIronMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassGatheringIronMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassGatheringIronMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassGatheringIronMaker.getStats() return {ironStock=GlassGatheringIronMaker.ironStock,bronzeStock=GlassGatheringIronMaker.bronzeStock,woodStock=GlassGatheringIronMaker.woodStock,leatherStock=GlassGatheringIronMaker.leatherStock,silverStock=GlassGatheringIronMaker.silverStock,goldStock=GlassGatheringIronMaker.goldStock,jewelStock=GlassGatheringIronMaker.jewelStock,pearlStock=GlassGatheringIronMaker.pearlStock,productStock=GlassGatheringIronMaker.productStock,numBuildings=#GlassGatheringIronMaker.buildings,hasMaker=GlassGatheringIronMaker.maker~=nil,makerName=GlassGatheringIronMaker.maker and GlassGatheringIronMaker.maker.name or "—",makerSkill=GlassGatheringIronMaker.maker and GlassGatheringIronMaker.maker.skill or 0,activeMaking=#GlassGatheringIronMaker.activeMaking,totalProducts=GlassGatheringIronMaker.totalProducts} end
return GlassGatheringIronMaker
